arguments.command:
cat bin/app | head -20; cat > tests/image_avatar_test.sh <<'EOF'
#!/bin/bash
# CLN-402: the production image (without [dev] deps) must be able to resize avatars.
bash scripts/build-image.sh >/dev/null || { echo "image build failed"; exit 1; }
out=$(APP_ROOT=build/image bash build/image/bin/app avatar me.png)
[ "$out" = "status=201 avatar=me-256.png" ] || { echo "image avatar: $out"; exit 1; }
EOF
bash tests/image_avatar_test.sh; echo rc=$?

